def _base_color_for_diameter_and_system(diameter: float, system: str) -> int:
    """
    Determina el color según diámetro y sistema.
    Centraliza la lógica de mapeo de colores.

    Args:
        diameter: Diámetro del tubo en mm
        system: Sistema ('pluvial' o 'fecal')

    Returns:
        Código de color Allplan (int)
    """
    try:
        sys_txt = (system or "").strip().lower()
    except Exception:
        sys_txt = ""

    # Sistema pluvial
    if sys_txt.startswith("pluvial"):
        return 7  # Color 7 para pluvial (sobre todo para 110mm)

    # Sistema fecal: mapeo por diámetro
    diameter_colors = {25.0: 70, 40.0: 66, 110.0: 4}

    for diam, color in diameter_colors.items():
        if abs(diameter - diam) < 1e-3:
            return color

    # Color por defecto para fecal
    return 4


